rule.example:

static LIMIT: AtomicUsize = AtomicUsize::new(10);

fn over_limit(count: usize) -> bool {
    count > LIMIT.load(Ordering::Relaxed) // implicit input
}

fn over_limit_explicit(count: usize, limit: usize) -> bool {
    count > limit
}


fn add_item(cart: &mut Vec<Item>, item: Item) { // implicit output
    cart.push(item);
}

fn add_item_explicit(cart: &[Item], item: Item) -> Vec<Item> {
    let mut next = cart.to_vec();
    next.push(item);
    next
}
